css:
body {
	margin: 0;
	font-family: sans-serif;
}

/* Global, so the keyframes keep their name: an animation event reports it. */
.notice[ui-closing] {
	animation: fold 400ms ease-in forwards;
}
@keyframes fold {
	from {
		background-color: #fff3cd;
	}
	to {
		background-color: #f8f9fa;
	}
}

.page.mk-17ddx0t {
				padding: 24px;
				background: #f8f9fa;
			}
			.heading.mk-17ddx0t {
				font-size: 26px;
				font-weight: 700;
				color: #212529;
			}
			.notice.mk-17ddx0t {
				margin-top: 16px;
				padding: 16px;
				border-radius: 10px;
				background: #fff3cd;
				color: #664d03;
				font-size: 17px;
			}
			.action.mk-17ddx0t {
				display: block;
				width: 100%;
				margin-top: 12px;
				padding: 10px 16px;
				border: 2px solid #264653;
				border-radius: 10px;
				background: #ffffff;
				color: #264653;
				font-family: inherit;
				font-size: 17px;
				text-align: left;
			}
			.status.mk-17ddx0t {
				margin-top: 24px;
				color: #495057;
				font-size: 15px;
			}
